const WILD={deer:{c:'#9a6a40',b:'#e8d8c0',L:1.35,H:0.95,W:0.42,leg:0.9,neck:0.55,head:0.32,ant:1},boar:{c:'#3a2e26',b:'#4a3a30',L:1.15,H:0.62,W:0.5,leg:0.45,neck:0.1,head:0.4,tusk:1},
 wolf:{c:'#7a7268',b:'#c8c0b4',L:1.0,H:0.6,W:0.34,leg:0.6,neck:0.25,head:0.3,ears:1},bear:{c:'#4a3424',b:'#5a4232',L:1.55,H:0.95,W:0.75,leg:0.6,neck:0.1,head:0.42,ears:1},
 hare:{c:'#9a846a',b:'#e0d4c4',L:0.42,H:0.26,W:0.2,leg:0.2,neck:0.08,head:0.15,long:1},ox:{c:'#eeeae0',b:'#dcd6c8',L:2.0,H:1.15,W:0.75,leg:0.85,neck:0.2,head:0.5,horn:1}};
function wildBuild(sp,o){const S=WILD[sp],g=new THREE.Group(),m=lam((o&&o.c&&o.c.coat)||S.c),mb=lam(S.b),dk=lam('#1e1814');
  const body=new THREE.Mesh(new THREE.SphereGeometry(1,12,8),m);body.scale.set(S.W,S.H*0.42,S.L*0.55);body.position.set(0,S.leg+S.H*0.3,0);body.castShadow=true;g.add(body);
  const head=new THREE.Group();head.position.set(0,S.leg+S.H*0.5+S.neck*0.6,-S.L*0.52);g.add(head);
  const hm=new THREE.Mesh(new THREE.SphereGeometry(1,10,7),m);hm.scale.set(S.head*0.55,S.head*0.55,S.head);hm.position.z=-S.head*0.5;head.add(hm);
  if(S.neck>0.15){const nk=new THREE.Mesh(new THREE.CylinderGeometry(S.W*0.32,S.W*0.42,S.neck*1.4,8),m);nk.rotation.x=-0.6;nk.position.set(0,-S.neck*0.45,S.head*0.2);head.add(nk);}
  if(S.ant)for(const s of[-1,1]){const a=new THREE.Mesh(new THREE.CylinderGeometry(0.02,0.035,0.55,5),lam('#cdb48a'));a.position.set(s*0.12,S.head*0.55+0.22,-S.head*0.2);a.rotation.z=s*0.5;head.add(a);for(const k of[0.1,0.25]){const t=new THREE.Mesh(new THREE.CylinderGeometry(0.012,0.02,0.22,4),lam('#cdb48a'));t.position.set(s*(0.12+k*0.7),S.head*0.55+0.1+k*1.2,-S.head*0.2-0.06);t.rotation.set(-0.5,0,s*0.2);head.add(t);}}
  if(S.tusk)for(const s of[-1,1]){const t=new THREE.Mesh(new THREE.ConeGeometry(0.025,0.14,5),lam('#efe8d8'));t.position.set(s*0.1,-0.04,-S.head*1.3);t.rotation.x=-2.4;head.add(t);}
  if(S.ears)for(const s of[-1,1]){const e=new THREE.Mesh(new THREE.ConeGeometry(0.05*S.head/0.3,0.12*S.head/0.3,4),m);e.position.set(s*S.head*0.35,S.head*0.5,-S.head*0.1);head.add(e);}
  if(S.long)for(const s of[-1,1]){const e=new THREE.Mesh(new THREE.CylinderGeometry(0.02,0.03,0.16,5),m);e.position.set(s*0.04,0.13,0);e.rotation.z=s*0.2;head.add(e);}
  if(S.horn)for(const s of[-1,1]){const h=new THREE.Mesh(new THREE.CylinderGeometry(0.03,0.05,0.4,6),lam('#d8ccb0'));h.position.set(s*0.26,S.head*0.45,-S.head*0.1);h.rotation.z=s*1.1;head.add(h);}
  const tail=new THREE.Mesh(new THREE.CylinderGeometry(0.03,0.05,S.L*0.25,5),S.long?mb:m);tail.position.set(0,S.leg+S.H*0.42,S.L*0.55);tail.rotation.x=0.9;g.add(tail);
  const legs=[];for(const[x,z]of[[-1,-1],[1,-1],[-1,1],[1,1]]){const lg=new THREE.Group();lg.position.set(x*S.W*0.55,S.leg+0.05,z*S.L*0.38);const lm=new THREE.Mesh(new THREE.CylinderGeometry(S.W*0.13,S.W*0.1,S.leg+0.05,6),m);lm.position.y=-(S.leg+0.05)/2;lg.add(lm);const hf=new THREE.Mesh(new THREE.CylinderGeometry(S.W*0.1,S.W*0.12,0.06,6),dk);hf.position.y=-(S.leg+0.05);lg.add(hf);g.add(lg);legs.push(lg);}
  g.scale.setScalar((o&&o.s)||1);scene.add(g);return{g,body,head,tail,legs,ex:{},sp};}
const animalNat=animal;animal=function(sp,o){if(WILD[sp])return wildBuild(sp,o);return animalNat(sp,o);};
Object.assign(FAUNA_INFO,{
 deer:{A:['Ciervo','El animal de Ártemis cazadora. Acteón la vio bañarse en una fuente del Citerón y la diosa lo convirtió en ciervo: sus propios perros lo despedazaron. Jenofonte enseña a cazar ciervos con perros y redes.','Ovidio, Metamorfosis III 138-252; Jenofonte, Cinegético IX'],R:['Ciervo','El animal de Diana. En el bosque de Nemi, junto a su lago, se le ofrecen exvotos con forma de ciervo. Los romanos ricos los crían en sus cotos de caza, los vivaria.','Varrón, Sobre el campo III 13']},
 boar:{A:['Jabalí','El más temido de la caza. Heracles atrapó vivo al de Erimanto, y Meleagro mató al de Calidón, enviado por Ártemis. Odiseo tenía en la pierna la cicatriz de un jabalí, y por ella lo reconoció su nodriza.','Homero, Odisea XIX 390-466; Apolodoro II 5, 4'],R:['Jabalí','El plato fuerte de los banquetes: Petronio cuenta que en la cena de Trimalción sirvieron un jabalí entero con cestillos de dátiles colgando de los colmillos.','Petronio, Satiricón 40']},
 wolf:{A:['Lobo','El lobo es el animal de Apolo Liceo y de Zeus Liceo, en Arcadia. Según el mito, el rey Licaón ofreció a Zeus carne humana y fue convertido en lobo. Los pastores guardan los rebaños con perros molosos.','Ovidio, Metamorfosis I 209-243; Pausanias VIII 2, 3'],R:['Lobo','Una loba amamantó a Rómulo y Remo, y su estatua de bronce está en el Capitolio. En la lengua de los sabinos, el lobo se llama hirpus: de ahí los Hirpi Sorani, los «lobos de Sorano», sacerdotes del Soracte.','Livio I 4; Servio, Comentario a la Eneida XI 785']},
 bear:{A:['Oso','En Arcadia se cuenta que Calisto, compañera de Ártemis, fue convertida en osa; Zeus la subió al cielo como la Osa Mayor, y a su hijo Arcas, el padre de los arcadios, como el Guardián de la Osa.','Ovidio, Metamorfosis II 401-530; Pausanias VIII 3, 6-7'],R:['Oso','En los montes de Italia aún quedan osos. Muchos acaban en los juegos del anfiteatro: Marcial escribe epigramas sobre osos de la arena.','Marcial, Libro de los espectáculos']},
 hare:{A:['Liebre','La presa favorita de los cazadores a pie: Jenofonte dedica casi todo su tratado de caza a perseguirla con perros laconios. Una liebre era un regalo de amor típico entre los atenienses.','Jenofonte, Cinegético V-VI'],R:['Liebre','Los romanos la crían en cercados, los leporaria. Se decía que comer liebre hacía más guapo durante siete días, y Marcial se burla de ello.','Marcial V 29; Plinio, Historia natural XXVIII 260']},
 ox:{R:['Buey blanco del Clitumno','Virgilio dice que los rebaños blancos y los toros que se sacrifican en los triunfos se bañan en el río Clitumno, y que de ahí sale su blancura. Por eso los bueyes de esta comarca son tan buscados para los grandes sacrificios.','Virgilio, Geórgicas II 146-148'],A:['Buey','El buey ara y tira de los carros.','']}});
// ---- piezas del paisaje
// el sitio llano más cercano (desnivel pequeño en un círculo de radio rad), para fuentes, eras y fiestas: en una ladera el agua o un corro de gente quedan flotando
function flatNear(x,z,rad,maxR){rad=rad||3;maxR=maxR||60;const sl=(px,pz)=>{const c=terrainH(px,pz);let m=0;for(let i=0;i<6;i++){const a=i/6*TAU;m=Math.max(m,Math.abs(terrainH(px+Math.cos(a)*rad,pz+Math.sin(a)*rad)-c));}return m;};
  let best=[x,z],bs=sl(x,z);if(bs<rad*0.12)return best;for(let r=8;r<=maxR;r+=8)for(let i=0;i<10;i++){const a=i/10*TAU+r*0.37,px=x+Math.cos(a)*r,pz=z+Math.sin(a)*r;if(riverWater&&riverWater(px,pz)!==null)continue;if(!isFree(px,pz,rad))continue;const v=sl(px,pz);if(v<bs){bs=v;best=[px,pz];if(v<rad*0.12)return best;}}return best;}
function natSpring(x,z){[x,z]=flatNear(x,z,2.4,70);const gy=terrainH(x,z),g=grp(x,gy,z,0);for(let i=0;i<10;i++){const a=i/10*TAU,r=new THREE.Mesh(new THREE.DodecahedronGeometry(0.35+R()*0.25,0),M.stone);r.position.set(Math.cos(a)*1.9,terrainH(x+Math.cos(a)*1.9,z+Math.sin(a)*1.9)-gy+0.15,Math.sin(a)*1.9);g.add(r);}
  let lo=0;for(let i=0;i<8;i++){const a=i/8*TAU;lo=Math.min(lo,terrainH(x+Math.cos(a)*1.7,z+Math.sin(a)*1.7)-gy);}const w=new THREE.Mesh(new THREE.CircleGeometry(1.7,20),new THREE.MeshLambertMaterial({color:'#4f8a96',transparent:true,opacity:0.85}));w.rotation.x=-Math.PI/2;w.position.y=lo+0.12;g.add(w);addCirc(x,z,2);return g;}
function natAltar(x,z,col){const gy=terrainH(x,z),g=grp(x,gy,z,R()*TAU);box(1.4,1,1,lam(col||'#d8ccb4'),0,0.5,0,g);box(1.6,0.15,1.2,lam('#c8bca4'),0,1.05,0,g);addCirc(x,z,1);return g;}
function natAshAltar(x,z){const gy=terrainH(x,z),g=grp(x,gy,z,0);const c=new THREE.Mesh(new THREE.ConeGeometry(4,2.4,14),lam('#4a4440'));c.position.y=1.1;g.add(c);for(const s of[-1,1]){const p=new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.4,5,10),lam('#d8ccb4'));p.position.set(s*3,2.5,-6);g.add(p);const e=new THREE.Mesh(new THREE.SphereGeometry(0.45,8,6),lam('#d6a640'));e.position.set(s*3,5.3,-6);g.add(e);addCirc(x+s*3,z-6,0.5);}addCirc(x,z,3.6);return g;}
function natKiln(x,z){const gy=terrainH(x,z),g=grp(x,gy,z,R()*TAU);const k=new THREE.Mesh(new THREE.ConeGeometry(2,2.4,10),lam('#5a4a3c'));k.position.y=1.2;g.add(k);const s=new THREE.Sprite(new THREE.SpriteMaterial({map:dustTex(),color:0x6a6460,transparent:true,opacity:0.5,depthWrite:false}));s.position.set(0,7,0);s.scale.set(5,10,1);g.add(s);addCirc(x,z,2.1);return g;}
function natReeds(x,z,n){const m=lam('#7a8a4a');for(let i=0;i<n;i++){const px=x+rr(-4,4),pz=z+rr(-4,4),h=rr(1.2,2.2),r=new THREE.Mesh(new THREE.CylinderGeometry(0.02,0.03,h,4),m);r.position.set(px,terrainH(px,pz)+h/2,pz);r.rotation.z=rr(-0.15,0.15);scene.add(r);}}
