function natTravSetup(){for(const id in NAT_TRAV){const I=ISLANDS.find(q=>q.id===id);if(!I||!I.arrive)continue;const T=NAT_TRAV[id],p=findFree(I.arrive.x+40,I.arrive.z+30,1);if(!p)continue;artPerson(p,T[2],'nat:tr_'+id,T[0],T[1]||'viajero',3);}}
const natActTr=natAct;natAct=function(o){const id=o.act.slice(4);if(id.startsWith('tr_')){const T=NAT_TRAV[id.slice(3)];if(T)vmS('✦',T[0],T[1]||'',`<p>${T[3]}</p>`,[vmBye]);return;}return natActTr(o);};
const natSetup0=natSetup;natSetup=function(){natSetup0();try{natTravSetup();}catch(e){console.warn('natTrav',e);}};

