for(const[id,k,map,dx,dz]of[['acteon','A','citeron',-30,24],['penteo','A','citeron',26,-20],['licaon','A','liceo',10,-60],['calisto','A','liceo',-26,20],['dafne','A','tempe',20,-16],['diluvio','A','parnaso',-20,20],['hercules','A','eta',16,-30],['aqueloo','A','achelous',20,10],['ino','A','escironides',24,22],['heliades','R','padus',-30,-14],['hipolito','R','nemi',58,-40]]){const o=OVID.find(q=>q.id===id);if(o)o[k]=['i',map,dx,dz];}
// ---- apariciones en los montes: ménades en el Citerón (invierno, de noche), Pan al atardecer en el Liceo, la cacería de Ártemis en el Taigeto (noche)
const NAT_APP={g:null,id:null,ph:0};
function natAppWant(){if(ui!=='play'||!state)return null;let I=null;try{I=islandOf(player.x);}catch(e){}if(!I)return null;const h=clock.h,mo=calNow().mo,night=h>=20.5||h<4.5;
  if(I.id==='citeron'&&night&&(mo>=10||mo<=1))return'menades';if(I.id==='liceo'&&h>=17.5&&h<20.5)return'pan';if(I.id==='taigeto'&&night)return'artemis';return null;}
function natAppBuild(kind){const I=islandOf(player.x),g=new THREE.Group(),a=R()*TAU,cx=player.x+Math.cos(a)*40,cz=player.z+Math.sin(a)*40;g.position.set(cx,floorAt(cx,cz),cz);scene.add(g);g.userData={kind,ps:[]};
  if(kind==='menades'){for(let i=0;i<6;i++){const p=makePerson({female:true,chiton:'#e8dcc8',himation:pick(['#6a2a4a','#4a2a5a','#7a3a2a']),hair:'#2a1e14'});g.add(p);g.userData.ps.push(p);const f=new THREE.Sprite(new THREE.SpriteMaterial({map:TORCH_TEX,blending:THREE.AdditiveBlending,transparent:true,depthWrite:false}));f.scale.set(1.2,1.6,1);f.position.y=2.4;p.add(f);}}
  if(kind==='pan'){const p=makePerson({chiton:'#6a4a2a',hair:'#3a2a1e',beard:true});g.add(p);g.userData.ps.push(p);}
  if(kind==='artemis'){const p=makePerson({female:true,chiton:'#f4f0e8',himation:'#c9a24a',hair:'#c9a24a'});g.add(p);g.userData.ps.push(p);const gl=new THREE.Sprite(new THREE.SpriteMaterial({map:TORCH_TEX,color:0xdfe8ff,blending:THREE.AdditiveBlending,transparent:true,depthWrite:false,opacity:0.6}));gl.scale.set(3,4,1);gl.position.y=1.2;p.add(gl);for(let i=0;i<2;i++){const d=wildBuild('deer',{});scene.remove(d.g);g.add(d.g);g.userData.ps.push(d.g);}}
  return g;}
function natAppTick(dt){const want=natAppWant();if(want!==NAT_APP.id){if(NAT_APP.g){scene.remove(NAT_APP.g);NAT_APP.g=null;}NAT_APP.id=want;if(want){NAT_APP.g=natAppBuild(want);NAT_APP.ph=0;NAT_APP.seen=false;}}
  const G=NAT_APP.g;if(!G)return;NAT_APP.ph+=dt;const t=NAT_APP.ph,k=G.userData.kind,ps=G.userData.ps;
  if(k==='menades')ps.forEach((p,i)=>{const a=t*0.8+i/ps.length*TAU;p.position.set(Math.cos(a)*4,Math.abs(Math.sin(t*4+i))*0.3,Math.sin(a)*4);p.rotation.y=-a;armUp(p,-2.4+Math.sin(t*5+i)*0.4,-1.2);});
  if(k==='pan'){armUp(ps[0],-1.3,-1.3);ps[0].rotation.y=Math.atan2(player.x-G.position.x,player.z-G.position.z);}
  if(k==='artemis'){const a=t*0.35;G.position.x+=Math.cos(a)*dt*6;G.position.z+=Math.sin(a)*dt*6;G.position.y=floorAt(G.position.x,G.position.z);ps.forEach((p,i)=>{p.position.set(i?6+i*3:0,0,i?-4:0);p.rotation.y=a+Math.PI/2;});}
  const d=Math.hypot(G.position.x-player.x,G.position.z-player.z);
  if(!NAT_APP.seen&&d<45){NAT_APP.seen=true;const z=natz();const key='ap_'+k;if(!z[key]){z[key]=1;save();setTimeout(()=>{if(ui!=='play')return;
    vmS(k==='pan'?'♪':'☾',k==='menades'?'Ménades en el monte':k==='pan'?'Pan al atardecer':'La cacería de Ártemis','lo que creían los antiguos',
     k==='menades'?'<p>Entre los pinos ves un corro de mujeres con antorchas, el pelo suelto y pieles de cervatillo, que bailan y gritan «¡Evohé!». Es una oreibasía, la subida al monte para celebrar a Dioniso, que algunas ciudades hacían cada dos años, en pleno invierno.</p><p class="sub">Fuentes: Eurípides, Las bacantes; Pausanias X 4, 3. Las ménades del mito despedazaban animales; las mujeres reales celebraban ritos nocturnos que los hombres no podían ver.</p>':
     k==='pan'?'<p>En la ladera, una figura con barba y patas de cabra toca la siringa mientras cae el sol. Los pastores de Arcadia decían que Pan dormía al mediodía y que había que guardar silencio para no despertarlo; al atardecer, en cambio, tocaba para las ninfas.</p><p class="sub">Fuentes: Teócrito, Idilio I 15-18; Himno homérico a Pan.</p>':
     '<p>A la luz de la luna pasa una cazadora con túnica corta y arco, seguida de dos ciervos: Ártemis, que según los poetas recorre de noche los montes del Taigeto con sus ninfas. Los espartanos la veneraban como Ártemis Ortia.</p><p class="sub">Fuente: Homero, Odisea VI 102-104 (Ártemis cazando por el Taigeto y el Erimanto).</p>',[vmBye]);},600);}}}

