Object.assign(MED_POS,{lerna:[22.72,37.55],erimanto:[21.8,37.97],estinfalo:[22.46,37.85],tenaro:[22.48,36.39]});
const epiWild0=epiWild;epiWild=function(S,sp,x,z,r,s,c){const A=wildBuild(sp,{s:s||1,c:c||{}});S.g.add(A.g);A.g.position.set(x,0,z);A.g.rotation.y=r||0;return A;};
function epiNeck(seg,bx,by,bz,dx,dy,dz,t,ph){seg.forEach((s,i)=>{const k=i/seg.length;s.position.set(bx+dx*k+Math.sin(t*2+ph+k*3)*0.6*k,by+dy*k+Math.sin(t*1.5+ph)*0.4*k,bz+dz*k);});}
Object.assign(SIMPLE_GR,{
 lerna:{label:'Lerna',blobs:[[-260,-220,220,120],[260,-240,200,90]],lake:[60,120,110,80],houses:4,spread:50,
  steles:[['lerna_fuentes','Las fuentes de Lerna','ΛΕΡΝΑ','Una costa pantanosa al sur de Argos, llena de manantiales y cañaverales. Aquí, bajo un plátano junto a la fuente Amimone, vivía la Hidra. Pausanias cuenta que en el lago Alcionio, que no tiene fondo, Dioniso bajó al Hades a buscar a su madre Sémele, y que aquí se celebran unos misterios de Deméter (II 36-37).']],
  extra(I){NAT_FOREST(I,260);natReeds(I.x+40,I.z+60,70);natSpring(I.x-60,I.z+40);natReeds(I.x-80,I.z+80,40);}},
 erimanto:{label:'el Erimanto',blobs:[[0,-200,330,210],[-280,180,190,90]],houses:2,spread:40,
  steles:[['folo','El centauro Folo','ΦΟΛΟΣ','En los bosques de Fóloe, junto al Erimanto, vivía el centauro Folo, que acogió a Heracles cuando venía a cazar el jabalí. Heracles le pidió vino, y al abrir la tinaja común de los centauros, el olor los atrajo a todos, furiosos. En la pelea, una flecha envenenada hirió por accidente al sabio Quirón, que siendo inmortal no podía morir del dolor (Apolodoro II 5, 4).']],
  extra(I){NAT_FOREST(I,620);caveMouth(I.x+120,I.z-60,0.5);}},
 estinfalo:{label:'el Estínfalo',blobs:[[-270,-200,230,120],[270,-200,220,110]],lake:[0,40,170,110],site:[-140,160,20],temple:{name:'Templo de Ártemis Estinfalia',W:10,L:18},houses:4,spread:50,
  steles:[['estinfalo_lago','El lago Estínfalo','ΣΤΥΜΦΑΛΙΣ','Un lago de montaña en el norte de Arcadia, que en invierno crece y en verano se convierte en pantano: el agua se escapa por una sima. Pausanias vio en el techo del templo de Ártemis Estinfalia las aves esculpidas, y detrás del templo, unas doncellas de mármol con patas de pájaro (VIII 22, 4-7).']],
  extra(I){NAT_FOREST(I,280);natReeds(I.x+40,I.z+150,60);natReeds(I.x-70,I.z-60,50);}},
 tenaro:{label:'el Ténaro',blobs:[[0,-150,300,150]],site:[80,140,18],temple:{name:'Templo de Poseidón Tenario',W:10,L:16},houses:2,spread:40,arr:[-300,-40],
  steles:[['tenaro_cueva','La cueva del Ténaro','ΤΑΙΝΑΡΟΝ','En la punta más al sur de Grecia, junto al templo de Poseidón, hay una cueva por la que, según los poetas, Heracles subió a Cerbero desde el Hades; por aquí bajó también Orfeo (Virgilio la llama «las fauces del Ténaro»). Pausanias la visitó y no vio ningún camino bajo tierra (III 25, 5).'],['arion','Arión y el delfín','ΑΡΙΩΝ','Heródoto cuenta que el músico Arión, arrojado al mar por unos marineros que querían robarle, fue llevado a hombros por un delfín hasta este cabo. En el templo de Poseidón había una figurilla de bronce de un hombre sobre un delfín (I 23-24). El templo es además un asilo: aquí se refugian los suplicantes, también los hilotas.']],
  extra(I){NAT_FOREST(I,140);caveMouth(I.x+40,I.z+90,Math.PI*0.3);}}});
Object.assign(NAT_NY,{
 lerna:{dx:-60,dz:52,n:'Amimone',s:'la ninfa de la fuente',c:'#dbe8ee',t:'<p>«Era una de las cincuenta hijas de Dánao. Argos estaba seca y vine a buscar agua; un sátiro me atacó y Poseidón me salvó. Luego clavó su tridente en la roca y brotaron estas fuentes. Bajo aquel plátano vivía la Hidra.»</p>',src:'Apolodoro II 1, 4; Pausanias II 37, 1'},
 erimanto:{dx:130,dz:-48,n:'Folo',s:'el centauro hospitalario',c:'#9a7a5a',g:'old',t:'<p>«Soy Folo. A diferencia de mis hermanos, sé tratar a los huéspedes: a Heracles le serví la carne asada, aunque yo la como cruda. Abrir aquella tinaja de vino fue un error… y luego, por curiosidad, saqué una de sus flechas, se me cayó en el pie y morí del veneno.»</p>',src:'Apolodoro II 5, 4'},
 estinfalo:{dx:-130,dz:150,n:'Ártemis Estinfalia',s:'señora del lago',c:'#f4f0e8',t:'<p>«Este lago es mío, y también los pájaros que lo pueblan. Los estinfalios dicen que las aves de Heracles eran del tamaño de grullas, con picos que atravesaban el bronce. Otros cuentan que en realidad venían de Arabia.»</p><p class="sub">Pausanias da las dos versiones y no se decide.</p>',src:'Pausanias VIII 22, 4-7'},
 tenaro:{dx:50,dz:100,n:'Sombra en la cueva',s:'un alma del Hades',c:'#c8d0dc',t:'<p>Una voz débil sale de la cueva: «Por aquí bajó Heracles a por Cerbero, con el permiso de Perséfone, y por aquí lo sacó, atado, sin usar armas, solo con sus brazos. El perro babeaba de miedo a la luz, y de su baba brotó una planta venenosa, el acónito.»</p>',src:'Apolodoro II 5, 12; Ovidio, Metamorfosis VII 406-419'}});
Object.assign(NAT_FA,{lerna:[['hare',2,-120,60,60],['boar',1,160,-60,60]],erimanto:[['boar',3,-100,-80,70],['bear',1,140,-120,60],['deer',2,-160,140,60]],estinfalo:[['goat',3,-200,-100,60]],tenaro:[['goat',5,-80,-60,70]]});
Object.assign(NAT_TRAV,{lerna:['Un iniciado en los misterios de Lerna','',{chiton:'#efe6d4',himation:'#4a6a5a'},'«Cada año, de noche, celebramos aquí los misterios de Deméter junto al lago. No puedo contarte más: el que habla de ellos ofende a la diosa.»'],
 erimanto:['Un cazador de Psófide','',{chiton:'#6a5a40',short:true,noHimation:true},'«El jabalí del Erimanto aún aparece en las historias de los viejos. En Cumas, al otro lado del mar, dicen tener sus colmillos; aquí en Psófide no nos lo creemos.»'],
 estinfalo:['Una pescadora del lago','',{female:true,chiton:'#9a8a6a',himation:'#5a5040'},'«En invierno el lago crece; en verano el agua se va por un agujero en la montaña y quedan charcas con anguilas. Los viejos dicen que el agujero llega hasta Argos.»'],
 tenaro:['Un hilota fugitivo','suplicante de Poseidón',{chiton:'#7a6a50',short:true,noHimation:true},'«Me he refugiado en el santuario: aquí nadie puede tocarme. Hace años los espartanos sacaron de aquí a unos suplicantes y los mataron; dicen que por eso Poseidón les mandó el gran terremoto.»']});
